<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Taxonomy\Service\ListTaxonomyReconciliationProposalsService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class TaxonomyReconciliationController { public function __construct(private readonly AuthService $auth,private readonly ListTaxonomyReconciliationProposalsService $proposals,private readonly ApiResponseFactory $responses){} public function list(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access):ResponseInterface{try{$user=$this->auth->currentUser($access);if(!in_array('ADMIN',$user->roles,true))throw new \LogicException();return $this->responses->success($response,$this->proposals->list(),(string)$request->getAttribute('request_id'));}catch(DomainException|UnavailableUserException|\LogicException){return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));}} }
